1	using QBrainAi.Support.Mcp.Services;
2	using Xunit;
3	
4	namespace QBrainAi.Support.Mcp.Tests.Services;
5	
6	/// <summary>
7	/// Tests the directory walk that both user-profile scans use (marker agent-plugin version resolution and the
8	/// session-log agent-history scan): a walk never follows a directory link or other reparse point, skips the
9	/// contents of any directory whose listing fails with an IO or access error, and keeps walking the rest.
10	/// </summary>
11	/// <remarks>
12	/// Requirement coverage: TR-MCP-WS-005 / AC-TR-MCP-WS-005-001 and TR-MCP-SESSIONLOG-006 /
13	/// AC-TR-MCP-SESSIONLOG-006-009 (operator 2026-10-20: "Fix scans in PR 87 (Recommended)"; triage
14	/// report b0e41c36). Test data: scripted in-memory directory trees (<see cref="ScriptedDirectoryTree"/>) whose
15	/// listings return fixed entries or throw the exceptions observed on PAYTON-LEGION2 as kingd (an untrusted mount
16	/// point), an access-denied folder, and a vanished folder; no file system is read. Expected outputs are derived
17	/// from the acceptance criteria: a directory is yielded when its parent lists it unless it is a link, its contents
18	/// are walked only when its own listing succeeds, and file links are yielded as files. Negative controls run
19	/// deliberately wrong walks (one that follows links, one that propagates listing errors as the legacy recursive
20	/// enumeration did, one that stops at the first error, one that drops an unlistable directory) over the same trees
21	/// and prove the walk assertion rejects each.
22	/// </remarks>
23	public sealed class DirectoryTreeWalkerTests
24	{
25	    private const string UntrustedMountPointMessage =
26	        "The path cannot be traversed because it contains an untrusted mount point.";
27	
28	    /// <summary>A walk under test: lists through <c>list</c> from <c>root</c> and returns what it yielded.</summary>
29	    private delegate (List<string> Directories, List<string> Files) WalkFunction(
30	        Func<string, IReadOnlyList<DirectoryListingEntry>> list,
31	        string root);
32	
33	    private static DirectoryListingEntry DirEntry(string path) => new(path, IsDirectory: true, IsLink: false);
34	
35	    private static DirectoryListingEntry DirLinkEntry(string path) => new(path, IsDirectory: true, IsLink: true);
36	
37	    private static DirectoryListingEntry FileEntry(string path) => new(path, IsDirectory: false, IsLink: false);
38	
39	    private static DirectoryListingEntry FileLinkEntry(string path) => new(path, IsDirectory: false, IsLink: true);
40	
41	    /// <summary>
42	    /// Scripted cases: the tree, the walk root, and the directories, files and listed directories the acceptance
43	    /// criteria require. Each case builds a fresh tree so the listing record starts empty.
44	    /// </summary>
45	    private static readonly Dictionary<string, (Func<ScriptedDirectoryTree> Tree, string Root, string[] Directories, string[] Files, string[] Listed)> Cases =
46	        new(StringComparer.Ordinal)
47	        {
48	            ["nested-tree"] = (
49	                () => new ScriptedDirectoryTree()
50	                    .Lists("/p", DirEntry("/p/a"), FileEntry("/p/f1"))
51	                    .Lists("/p/a", DirEntry("/p/a/b"), FileEntry("/p/a/f2"))
52	                    .Lists("/p/a/b", FileEntry("/p/a/b/f3")),
53	                "/p",
54	                ["/p/a", "/p/a/b"],
55	                ["/p/f1", "/p/a/f2", "/p/a/b/f3"],
56	                ["/p", "/p/a", "/p/a/b"]),
57	            ["untrusted-mount-point"] = (
58	                () => new ScriptedDirectoryTree()
59	                    .Lists("/p", DirEntry("/p/bad"), DirEntry("/p/good"))
60	                    .Throws("/p/bad", () => new IOException(UntrustedMountPointMessage))
61	                    .Lists("/p/good", DirEntry("/p/good/inner"), FileEntry("/p/good/g.md"))
62	                    .Lists("/p/good/inner", FileEntry("/p/good/inner/i.md")),
63	                "/p",
64	                ["/p/bad", "/p/good", "/p/good/inner"],
65	                ["/p/good/g.md", "/p/good/inner/i.md"],
66	                ["/p", "/p/bad", "/p/good", "/p/good/inner"]),
67	            ["access-denied"] = (
68	                () => new ScriptedDirectoryTree()
69	                    .Lists("/p", DirEntry("/p/locked"), DirEntry("/p/open"))
70	                    .Throws("/p/locked", () => new UnauthorizedAccessException("Access to the path is denied."))
71	                    .Lists("/p/open", FileEntry("/p/open/o.md")),
72	                "/p",
73	                ["/p/locked", "/p/open"],
74	                ["/p/open/o.md"],
75	                ["/p", "/p/locked", "/p/open"]),
76	            ["vanished-directory"] = (
77	                () => new ScriptedDirectoryTree()
78	                    .Lists("/p", DirEntry("/p/gone"), DirEntry("/p/here"))
79	                    .Throws("/p/gone", () => new DirectoryNotFoundException("Could not find a part of the path."))
80	                    .Lists("/p/here", FileEntry("/p/here/h.md")),
81	                "/p",
82	                ["/p/gone", "/p/here"],
83	                ["/p/here/h.md"],
84	                ["/p", "/p/gone", "/p/here"]),
85	            ["directory-link"] = (
86	                () => new ScriptedDirectoryTree()
87	                    .Lists("/p", DirEntry("/p/real"), DirLinkEntry("/p/link"), FileEntry("/p/f"))
88	                    .Lists("/p/real", FileEntry("/p/real/x.md"))
89	                    .Lists("/p/link", FileEntry("/p/link/y.md")),
90	                "/p",
91	                ["/p/real"],
92	                ["/p/f", "/p/real/x.md"],
93	                ["/p", "/p/real"]),
94	            ["file-link"] = (
95	                () => new ScriptedDirectoryTree()
96	                    .Lists("/p", FileLinkEntry("/p/linked.md"), FileEntry("/p/plain.md")),
97	                "/p",
98	                [],
99	                ["/p/linked.md", "/p/plain.md"],
100	                ["/p"]),
101	            ["root-unlistable"] = (
102	                () => new ScriptedDirectoryTree()
103	                    .Throws("/p", () => new IOException(UntrustedMountPointMessage)),
104	                "/p",
105	                [],
106	                [],
107	                ["/p"]),
108	        };
109	
110	    /// <summary>The scripted case names, for the theories.</summary>
111	    public static TheoryData<string> CaseNames => new(Cases.Keys.Order(StringComparer.Ordinal));
112	
113	    /// <summary>
114	    /// Asserts one walk result against a case: the yielded directories, the yielded files, and the directories
115	    /// the walk listed, each compared as an ordinal set (the acceptance criteria fix membership, not order).
116	    /// </summary>
117	    private static void AssertWalk(
118	        (string[] Directories, string[] Files, string[] Listed) expected,
119	        IEnumerable<string> directories,
120	        IEnumerable<string> files,
121	        IEnumerable<string> listed)
122	    {
123	        Assert.Equal(expected.Directories.Order(StringComparer.Ordinal), directories.Order(StringComparer.Ordinal));
124	        Assert.Equal(expected.Files.Order(StringComparer.Ordinal), files.Order(StringComparer.Ordinal));
125	        Assert.Equal(
126	            expected.Listed.Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal),
127	            listed.Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal));
128	    }
129	
130	    /// <summary>Runs one walk over a fresh copy of a case's tree and asserts its result.</summary>
131	    private static void RunAndAssert(string name, WalkFunction walk)
132	    {
133	        var (treeFactory, root, directories, files, listed) = Cases[name];
134	        var tree = treeFactory();
135	        var result = walk(tree.List, root);
136	        AssertWalk((directories, files, listed), result.Directories, result.Files, tree.Listed);
137	    }
138	
139	    /// <summary>
140	    /// Mock gate positive control: each case's required output passes the walk assertion.
141	    /// </summary>
142	    /// <param name="name">Scripted case name.</param>
143	    [Theory]
144	    [MemberData(nameof(CaseNames))]
145	    public void ScriptedCase_RequiredOutput_PassesTheWalkAssertion(string name)
146	    {
147	        var (_, _, directories, files, listed) = Cases[name];
148	        AssertWalk((directories, files, listed), directories, files, listed);
149	    }
150	
151	    /// <summary>The theories cover every scripted case.</summary>
152	    [Fact]
153	    public void ScriptedTheory_CoversEveryCase() => Assert.Equal(7, Cases.Count);
154	
155	    /// <summary>
156	    /// The scripted tree is itself correct: it records every listing in order, returns the scripted entries,
157	    /// throws the scripted exception, and refuses a directory it was not given, so a walk that lists a link
158	    /// it should have skipped fails loudly.
159	    /// </summary>
160	    [Fact]
161	    public void ScriptedTree_RecordsListingsAndRefusesUnscriptedDirectories()
162	    {
163	        var tree = new ScriptedDirectoryTree()
164	            .Lists("/p", DirEntry("/p/a"))
165	            .Throws("/p/a", () => new IOException(UntrustedMountPointMessage));
166	
167	        Assert.Equal(new[] { DirEntry("/p/a") }, tree.List("/p"));
168	        Assert.Equal(UntrustedMountPointMessage, Assert.Throws<IOException>(() => tree.List("/p/a")).Message);
169	        Assert.Throws<InvalidOperationException>(() => tree.List("/p/unscripted"));
170	        Assert.Equal(new[] { "/p", "/p/a", "/p/unscripted" }, tree.Listed);
171	    }
172	
173	    /// <summary>
174	    /// Mock gate negative controls: each wrong walk is rejected by the walk assertion on the case that exposes it,
175	    /// inside a passing harness. The legacy recursive enumeration (follows links, propagates listing errors) fails
176	    /// on the untrusted mount point, the access-denied folder, the vanished folder, the unlistable root and the
177	    /// directory link; a walk that follows links fails on the directory link; a walk that stops at the first
178	    /// listing error loses the healthy sibling; a walk that drops an unlistable directory loses its entry.
179	    /// </summary>
180	    [Fact]
181	    public void WrongWalkNegativeControls_AreRejectedInsidePassingHarness()
182	    {
183	        foreach (var name in new[] { "untrusted-mount-point", "access-denied", "vanished-directory", "root-unlistable", "directory-link" })
184	            Assert.NotNull(Record.Exception(() => RunAndAssert(name, LegacyRecursiveWalk)));
185	
186	        Assert.NotNull(Record.Exception(() => RunAndAssert("directory-link", FollowsLinksWalk)));
187	        Assert.NotNull(Record.Exception(() => RunAndAssert("untrusted-mount-point", StopsAtFirstErrorWalk)));
188	        Assert.NotNull(Record.Exception(() => RunAndAssert("untrusted-mount-point", DropsUnlistableDirectoryWalk)));
189	
190	        // Each wrong walk is wrong only where a case exposes it: on the nested tree, which has no link and no
191	        // listing error, every one of them yields the required output, so the rejections above come from the
192	        // behavior under test and not from an assertion that rejects everything.
193	        foreach (var walk in new WalkFunction[] { LegacyRecursiveWalk, FollowsLinksWalk, StopsAtFirstErrorWalk, DropsUnlistableDirectoryWalk })
194	            Assert.Null(Record.Exception(() => RunAndAssert("nested-tree", walk)));
195	    }
196	
197	    /// <summary>
198	    /// Mock gate negative control for the error filter: a scripted listing error that is neither an IO nor an
199	    /// access error escapes the scripted tree, and a walk with a catch-all filter hides it; the production
200	    /// binding requires the walk to let it propagate.
201	    /// </summary>
202	    [Fact]
203	    public void UnexpectedListingError_EscapesTheScriptedTree()
204	    {
205	        var tree = new ScriptedDirectoryTree()
206	            .Lists("/p", DirEntry("/p/a"))
207	            .Throws("/p/a", () => new InvalidOperationException("not an IO error"));
208	
209	        Assert.Throws<InvalidOperationException>(() => LegacyRecursiveWalk(tree.List, "/p"));
210	        Assert.Null(Record.Exception(() => SwallowsEverythingWalk(tree.List, "/p")));
211	    }
212	
213	    /// <summary>
214	    /// Production binding of the scripted cases: <see cref="DirectoryTreeWalker"/> over each scripted tree yields
215	    /// the required directories and files, and both its directory walk and its file walk list exactly the required
216	    /// directories (never a link, never the contents of an unlistable directory).
217	    /// </summary>
218	    /// <param name="name">Scripted case name.</param>
219	    [Theory]
220	    [MemberData(nameof(CaseNames))]
221	    public void ScriptedCase_ProductionWalk_YieldsTheRequiredOutput(string name)
222	    {
223	        var (treeFactory, root, directories, files, listed) = Cases[name];
224	        var directoryTree = treeFactory();
225	        var fileTree = treeFactory();
226	
227	        var yieldedDirectories = new DirectoryTreeWalker(directoryTree.List).EnumerateDirectories(root).ToList();
228	        var yieldedFiles = new DirectoryTreeWalker(fileTree.List).EnumerateFiles(root).ToList();
229	
230	        AssertWalk((directories, files, listed), yieldedDirectories, yieldedFiles, directoryTree.Listed);
231	        AssertWalk((directories, files, listed), yieldedDirectories, yieldedFiles, fileTree.Listed);
232	    }
233	
234	    /// <summary>
235	    /// Production binding of the error filter: a listing error that is neither an IO nor an access error
236	    /// propagates out of <see cref="DirectoryTreeWalker"/> instead of being skipped.
237	    /// </summary>
238	    [Fact]
239	    public void ProductionWalk_UnexpectedListingError_Propagates()
240	    {
241	        var tree = new ScriptedDirectoryTree()
242	            .Lists("/p", DirEntry("/p/a"))
243	            .Throws("/p/a", () => new InvalidOperationException("not an IO error"));
244	
245	        Assert.Throws<InvalidOperationException>(() => new DirectoryTreeWalker(tree.List).EnumerateDirectories("/p").ToList());
246	        Assert.Throws<ArgumentNullException>(() => new DirectoryTreeWalker(null!));
247	    }
