249	    /// <summary>
250	    /// Integration: on the real file system, <see cref="DirectoryTreeWalker.ListFileSystem"/> flags a directory
251	    /// symbolic link and a file symbolic link as links, and <see cref="DirectoryTreeWalker.FileSystem"/> neither
252	    /// yields nor descends the directory link (whose target lies outside the walked tree) while it yields the file
253	    /// link as a file. Creating symbolic links depends on the host (on Windows, Developer Mode or the
254	    /// create-symbolic-link privilege), so this is an integration test.
255	    /// </summary>
256	    [Fact]
257	    [Trait("Category", "Integration")]
258	    public void FileSystemWalk_RealLinks_AreFlaggedAndNotDescended()
259	    {
260	        var root = Path.Combine(Path.GetTempPath(), $"mcp-walk-links-{Guid.NewGuid():N}");
261	        var outside = root + "-outside";
262	        var real = Path.Combine(root, "real");
263	        var realFile = Path.Combine(real, "x.md");
264	        var directoryLink = Path.Combine(root, "dir-link");
265	        var fileLink = Path.Combine(root, "file-link.md");
266	        Directory.CreateDirectory(real);
267	        Directory.CreateDirectory(outside);
268	        System.IO.File.WriteAllText(realFile, "x");
269	        System.IO.File.WriteAllText(Path.Combine(outside, "y.md"), "y");
270	        try
271	        {
272	            Directory.CreateSymbolicLink(directoryLink, outside);
273	            System.IO.File.CreateSymbolicLink(fileLink, realFile);
274	
275	            var entries = DirectoryTreeWalker.ListFileSystem(root);
276	            Assert.Contains(new DirectoryListingEntry(directoryLink, IsDirectory: true, IsLink: true), entries);
277	            Assert.Contains(new DirectoryListingEntry(fileLink, IsDirectory: false, IsLink: true), entries);
278	            Assert.Contains(new DirectoryListingEntry(real, IsDirectory: true, IsLink: false), entries);
279	
280	            Assert.Equal(new[] { real }, DirectoryTreeWalker.FileSystem.EnumerateDirectories(root));
281	            Assert.Equal(
282	                new[] { fileLink, realFile }.Order(StringComparer.Ordinal),
283	                DirectoryTreeWalker.FileSystem.EnumerateFiles(root).Order(StringComparer.Ordinal));
284	        }
285	        finally
286	        {
287	            if (System.IO.File.Exists(fileLink))
288	                System.IO.File.Delete(fileLink);
289	            if (Directory.Exists(directoryLink))
290	                Directory.Delete(directoryLink);
291	            Directory.Delete(root, recursive: true);
292	            Directory.Delete(outside, recursive: true);
293	        }
294	    }
