339	    private static (List<string> Directories, List<string> Files) ConfigurableWalk(
340	        Func<string, IReadOnlyList<DirectoryListingEntry>> list,
341	        string root,
342	        bool skipLinks,
343	        bool stopAtFirstError,
344	        bool yieldUnlistable,
345	        bool catchAll)
346	    {
347	        var directories = new List<string>();
348	        var files = new List<string>();
349	        var pending = new Queue<string>([root]);
350	        while (pending.Count > 0)
351	        {
352	            var directory = pending.Dequeue();
353	            IReadOnlyList<DirectoryListingEntry> entries;
354	            try
355	            {
356	                entries = list(directory);
357	            }
358	            catch (Exception ex) when (catchAll || ex is IOException or UnauthorizedAccessException)
359	            {
360	                if (!yieldUnlistable)
361	                    directories.Remove(directory);
362	                if (stopAtFirstError)
363	                    break;
364	                continue;
365	            }
366	
367	            foreach (var entry in entries)
368	            {
369	                if (entry.IsDirectory && entry.IsLink && skipLinks)
370	                    continue;
371	                if (entry.IsDirectory)
372	                {
373	                    directories.Add(entry.Path);
374	                    pending.Enqueue(entry.Path);
375	                }
376	                else
377	                {
378	                    files.Add(entry.Path);
379	                }
380	            }
381	        }
382	
383	        return (directories, files);
384	    }
