386	    /// <summary>
387	    /// Scripted in-memory directory tree: each directory lists fixed entries or throws a fixed exception, every
388	    /// listing is recorded in order, and an unscripted directory throws <see cref="InvalidOperationException"/>.
389	    /// </summary>
390	    private sealed class ScriptedDirectoryTree
391	    {
392	        private readonly Dictionary<string, Func<IReadOnlyList<DirectoryListingEntry>>> _listings = new(StringComparer.Ordinal);
393	
394	        /// <summary>Directories listed so far, in order.</summary>
395	        public List<string> Listed { get; } = [];
396	
397	        /// <summary>Scripts <paramref name="directory"/> to list <paramref name="entries"/>.</summary>
398	        public ScriptedDirectoryTree Lists(string directory, params DirectoryListingEntry[] entries)
399	        {
400	            _listings[directory] = () => entries;
401	            return this;
402	        }
403	
404	        /// <summary>Scripts <paramref name="directory"/> to throw the exception <paramref name="error"/> creates.</summary>
405	        public ScriptedDirectoryTree Throws(string directory, Func<Exception> error)
406	        {
407	            _listings[directory] = () => throw error();
408	            return this;
409	        }
410	
411	        /// <summary>Lists one directory as scripted.</summary>
412	        public IReadOnlyList<DirectoryListingEntry> List(string directory)
413	        {
414	            Listed.Add(directory);
415	            if (!_listings.TryGetValue(directory, out var listing))
416	                throw new InvalidOperationException($"Unscripted directory listed: {directory}");
417	            return listing();
418	        }
419	    }
